import React, { useEffect } from 'react';
import { Alert, Box, Link, Paper, Typography } from '@mui/material';
import { Link as RouterLink, useNavigate, useSearchParams } from 'react-router-dom';
import AccountingConnectorsPanel from './AccountingConnectorsPanel';

/**
 * Data → Data connectors: self-serve links to Tally, Zoho, QuickBooks, and other accounting tools.
 * Document upload and library live under Documents (/document-upload).
 */
const DataConnectorsPage: React.FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();

  useEffect(() => {
    if (searchParams.has('tab')) {
      navigate('/document-upload', { replace: true });
      return;
    }
    if (searchParams.get('section') === 'operational') {
      navigate('/carbon-footprint?section=operational', { replace: true });
      return;
    }
    if (!searchParams.get('section')) {
      setSearchParams(
        (prev) => {
          const next = new URLSearchParams(prev);
          next.set('section', 'connectors');
          return next;
        },
        { replace: true }
      );
    }
  }, [navigate, searchParams, setSearchParams]);

  if (searchParams.has('tab') || searchParams.get('section') === 'operational') {
    return null;
  }

  return (
    <Box>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
        Connect TallyPrime, Zoho Books, QuickBooks, and other Indian accounting software. Use live API sync
        where supported, or import JSON and CSV exports—your activity data flows into carbon calculations and
        reporting.
      </Typography>

      <Paper id="data-connectors" variant="outlined" sx={{ p: 3 }}>
        <Typography variant="h6" component="h2" sx={{ fontWeight: 600, mb: 0.5 }}>
          Accounting software connectors
        </Typography>
        <AccountingConnectorsPanel />
      </Paper>

      <Alert severity="info" sx={{ mt: 3 }}>
        To upload utility bills, invoices, or other supporting documents, use{' '}
        <Link component={RouterLink} to="/document-upload">
          Documents
        </Link>
        .
      </Alert>
    </Box>
  );
};

export default DataConnectorsPage;
